function solve({config,state,event}){
  function cmp(a,b){let x=Array.from(a),y=Array.from(b),n=Math.min(x.length,y.length);for(let i=0;i<n;i++){let u=x[i].codePointAt(0),v=y[i].codePointAt(0);if(u!==v)return u-v}return x.length-y.length}
  let s=state||{head:null,records:{}};
  let r=s.records, bad=false, add={};
  for(let q of event.records){let old=r[q.id]||add[q.id];if(old&&(old.parent!==q.parent||old.value!==q.value)){bad=true;break}add[q.id]={parent:q.parent,value:q.value}}
  function walk(h){let seen={},miss={};let x=h;while(x!==null){if(!r[x]&&!(!bad&&add[x])){miss[x]=1;break}if(seen[x])break;seen[x]=1;x=(r[x]||add[x]).parent}return {seen:seen,term:x,miss:miss}}
  let a=walk(s.head),b=walk(event.head),m={};for(let x in a.miss)m[x]=1;for(let x in b.miss)m[x]=1;let missing=Object.keys(m).sort(cmp),out,ns=s;
  if(bad)out={head:s.head,decision:'conflict',missing};
  else{let d,h=s.head;if(s.head===event.head)d='same';else if((s.head===null?b.term===null:!!b.seen[s.head])){d='advance';h=event.head;ns={head:h,records:Object.assign({},r,add)}}else if((event.head===null?a.term===null:!!a.seen[event.head]))d='ahead';else if(a.term===null&&b.term===null)d='fork';else d='unknown';if(d==='advance')ns={head:h,records:Object.assign({},r,add)};out={head:ns.head,decision:d,missing}}return {state:ns,output:out}
}
